CREATE TABLE `saved_commands` (
	`id` text PRIMARY KEY NOT NULL,
	`name` text NOT NULL,
	`description` text NOT NULL,
	`scripts` text NOT NULL,
	`parameters` text NOT NULL,
	`machine_group_ids` text NOT NULL,
	`effect` text NOT NULL,
	`enabled` integer NOT NULL,
	`ai_unattended` integer NOT NULL,
	`timeout_ms` integer NOT NULL,
	`version` integer NOT NULL,
	`created_at` integer NOT NULL,
	`updated_at` integer NOT NULL,
	`updated_by` text,
	FOREIGN KEY (`updated_by`) REFERENCES `users`(`id`) ON UPDATE no action ON DELETE no action
);
--> statement-breakpoint
CREATE UNIQUE INDEX `saved_commands_name_unique` ON `saved_commands` (`name`);--> statement-breakpoint
ALTER TABLE `command_runs` ADD `saved_command_id` text;--> statement-breakpoint
ALTER TABLE `command_runs` ADD `saved_command_name` text;--> statement-breakpoint
ALTER TABLE `command_runs` ADD `saved_command_version` integer;--> statement-breakpoint
ALTER TABLE `command_runs` ADD `saved_command_effect` text;--> statement-breakpoint
ALTER TABLE `command_runs` ADD `saved_command_values` text;--> statement-breakpoint
ALTER TABLE `command_runs` ADD `pre_approved` integer DEFAULT false NOT NULL;--> statement-breakpoint
INSERT INTO `saved_commands` (`id`, `name`, `description`, `scripts`, `parameters`, `machine_group_ids`, `effect`, `enabled`, `ai_unattended`, `timeout_ms`, `version`, `created_at`, `updated_at`, `updated_by`) VALUES ('00000000-0000-4000-8000-00000005c001', 'Check for updates', 'Lists the updates waiting, without installing any. On Linux it refreshes the package lists first (dnf, apt or zypper); on Windows it asks Windows Update.', '[{"osFamily":"windows","shell":"powershell","script":"$session = New-Object -ComObject Microsoft.Update.Session\n$searcher = $session.CreateUpdateSearcher()\n$result = $searcher.Search(''IsInstalled=0 and IsHidden=0'')\nif ($result.Updates.Count -eq 0) {\n  ''No updates waiting.''\n} else {\n  \"$($result.Updates.Count) updates waiting:\"\n  foreach ($update in $result.Updates) { \" - $($update.Title)\" }\n}"},{"osFamily":"linux","shell":"sh","script":"if command -v dnf >/dev/null 2>&1; then\n  echo \"Package manager: dnf\"\n  dnf -q check-update\n  status=$?\n  if [ \"$status\" -eq 100 ]; then echo \"Updates are waiting (listed above).\"; exit 0; fi\n  if [ \"$status\" -eq 0 ]; then echo \"No updates waiting.\"; fi\n  exit \"$status\"\nelif command -v apt-get >/dev/null 2>&1; then\n  echo \"Package manager: apt\"\n  apt-get update -qq >/dev/null 2>&1 || echo \"Could not refresh the package lists; showing what is known.\"\n  apt list --upgradable 2>/dev/null\nelif command -v zypper >/dev/null 2>&1; then\n  echo \"Package manager: zypper\"\n  zypper --non-interactive --quiet list-updates\nelse\n  echo \"No dnf, apt or zypper on this machine.\"\n  exit 1\nfi"}]', '[]', '["00000000-0000-4000-8000-00000000a11a"]', 'reads-only', 0, 0, 300000, 1, 0, 0, NULL);--> statement-breakpoint
INSERT INTO `saved_commands` (`id`, `name`, `description`, `scripts`, `parameters`, `machine_group_ids`, `effect`, `enabled`, `ai_unattended`, `timeout_ms`, `version`, `created_at`, `updated_at`, `updated_by`) VALUES ('00000000-0000-4000-8000-00000005c002', 'Disk space', 'Size, free space and use of each fixed disk.', '[{"osFamily":"windows","shell":"powershell","script":"Get-CimInstance Win32_LogicalDisk -Filter ''DriveType=3'' |\n  Select-Object DeviceID, VolumeName,\n    @{ n = ''SizeGB''; e = { [math]::Round($_.Size / 1GB, 1) } },\n    @{ n = ''FreeGB''; e = { [math]::Round($_.FreeSpace / 1GB, 1) } },\n    @{ n = ''FreePercent''; e = { if ($_.Size) { [math]::Round(100 * $_.FreeSpace / $_.Size) } else { 0 } } } |\n  Format-Table -AutoSize | Out-String -Width 200"},{"osFamily":"linux","shell":"sh","script":"df -h -x tmpfs -x devtmpfs -x squashfs -x overlay 2>/dev/null || df -h"}]', '[]', '["00000000-0000-4000-8000-00000000a11a"]', 'reads-only', 0, 0, 60000, 1, 0, 0, NULL);--> statement-breakpoint
INSERT INTO `saved_commands` (`id`, `name`, `description`, `scripts`, `parameters`, `machine_group_ids`, `effect`, `enabled`, `ai_unattended`, `timeout_ms`, `version`, `created_at`, `updated_at`, `updated_by`) VALUES ('00000000-0000-4000-8000-00000005c003', 'Uptime and last boot', 'How long the machine has been up, when it last started, and its load.', '[{"osFamily":"windows","shell":"powershell","script":"$os = Get-CimInstance Win32_OperatingSystem\n$up = (Get-Date) - $os.LastBootUpTime\n\"Last boot: $($os.LastBootUpTime)\"\n\"Up: $($up.Days) days, $($up.Hours) hours, $($up.Minutes) minutes\""},{"osFamily":"linux","shell":"sh","script":"echo \"Uptime: $(uptime -p 2>/dev/null || uptime)\"\necho \"Last boot: $(uptime -s 2>/dev/null || who -b)\"\necho \"Load (1, 5, 15 min): $(cut -d '' '' -f 1-3 /proc/loadavg)\""}]', '[]', '["00000000-0000-4000-8000-00000000a11a"]', 'reads-only', 0, 0, 60000, 1, 0, 0, NULL);--> statement-breakpoint
INSERT INTO `saved_commands` (`id`, `name`, `description`, `scripts`, `parameters`, `machine_group_ids`, `effect`, `enabled`, `ai_unattended`, `timeout_ms`, `version`, `created_at`, `updated_at`, `updated_by`) VALUES ('00000000-0000-4000-8000-00000005c004', 'Top processes', 'The ten processes using the most CPU and the ten using the most memory.', '[{"osFamily":"windows","shell":"powershell","script":"$columns = ''Id'', ''ProcessName'',\n  @{ n = ''CPUSeconds''; e = { [math]::Round($_.CPU, 1) } },\n  @{ n = ''MemoryMB''; e = { [math]::Round($_.WorkingSet64 / 1MB) } }\n''Top by CPU time:''\nGet-Process | Sort-Object CPU -Descending | Select-Object -First 10 $columns | Format-Table -AutoSize | Out-String -Width 200\n''Top by memory:''\nGet-Process | Sort-Object WorkingSet64 -Descending | Select-Object -First 10 $columns | Format-Table -AutoSize | Out-String -Width 200"},{"osFamily":"linux","shell":"sh","script":"echo \"Top by CPU:\"\nps -eo pid,user,pcpu,pmem,comm --sort=-pcpu | head -n 11\necho\necho \"Top by memory:\"\nps -eo pid,user,pcpu,pmem,comm --sort=-pmem | head -n 11"}]', '[]', '["00000000-0000-4000-8000-00000000a11a"]', 'reads-only', 0, 0, 60000, 1, 0, 0, NULL);--> statement-breakpoint
INSERT INTO `saved_commands` (`id`, `name`, `description`, `scripts`, `parameters`, `machine_group_ids`, `effect`, `enabled`, `ai_unattended`, `timeout_ms`, `version`, `created_at`, `updated_at`, `updated_by`) VALUES ('00000000-0000-4000-8000-00000005c005', 'Service status', 'Whether a service is running, and its recent log lines on Linux.', '[{"osFamily":"windows","shell":"powershell","script":"Get-Service -Name $env:BMUSTER_PARAM_SERVICE -ErrorAction Stop |\n  Format-List Name, DisplayName, Status, StartType"},{"osFamily":"linux","shell":"sh","script":"if command -v systemctl >/dev/null 2>&1; then\n  systemctl status --no-pager --lines=20 -- \"$BMUSTER_PARAM_SERVICE\"\nelse\n  service \"$BMUSTER_PARAM_SERVICE\" status\nfi"}]', '[{"kind":"text","name":"service","label":"Service","pattern":"service-name"}]', '["00000000-0000-4000-8000-00000000a11a"]', 'reads-only', 0, 0, 60000, 1, 0, 0, NULL);--> statement-breakpoint
INSERT INTO `saved_commands` (`id`, `name`, `description`, `scripts`, `parameters`, `machine_group_ids`, `effect`, `enabled`, `ai_unattended`, `timeout_ms`, `version`, `created_at`, `updated_at`, `updated_by`) VALUES ('00000000-0000-4000-8000-00000005c006', 'Recent system errors', 'Errors the system logged in the last few hours (at most 200).', '[{"osFamily":"windows","shell":"powershell","script":"$since = (Get-Date).AddHours(-[int]$env:BMUSTER_PARAM_HOURS)\n$events = Get-WinEvent -FilterHashtable @{ LogName = ''System'', ''Application''; Level = 1, 2; StartTime = $since } -MaxEvents 200 -ErrorAction SilentlyContinue\nif (-not $events) {\n  \"No errors in the last $env:BMUSTER_PARAM_HOURS hours.\"\n} else {\n  $events | Select-Object TimeCreated, LogName, ProviderName, Id,\n    @{ n = ''Message''; e = { ($_.Message -split [Environment]::NewLine)[0] } } |\n    Format-Table -AutoSize -Wrap | Out-String -Width 250\n}"},{"osFamily":"linux","shell":"sh","script":"if command -v journalctl >/dev/null 2>&1; then\n  journalctl --no-pager --priority=err --since \"$BMUSTER_PARAM_HOURS hours ago\" | tail -n 200\nelse\n  echo \"No journalctl; showing the end of the system log.\"\n  tail -n 200 /var/log/messages 2>/dev/null || tail -n 200 /var/log/syslog\nfi"}]', '[{"kind":"number","name":"hours","label":"Hours","min":1,"max":72}]', '["00000000-0000-4000-8000-00000000a11a"]', 'reads-only', 0, 0, 120000, 1, 0, 0, NULL);--> statement-breakpoint
INSERT INTO `saved_commands` (`id`, `name`, `description`, `scripts`, `parameters`, `machine_group_ids`, `effect`, `enabled`, `ai_unattended`, `timeout_ms`, `version`, `created_at`, `updated_at`, `updated_by`) VALUES ('00000000-0000-4000-8000-00000005c007', 'Network settings', 'Addresses, gateways and DNS servers of each network interface.', '[{"osFamily":"windows","shell":"powershell","script":"Get-NetIPConfiguration | ForEach-Object {\n  \"Interface: $($_.InterfaceAlias)\"\n  \"  IPv4: $(($_.IPv4Address | ForEach-Object IPAddress) -join '', '')\"\n  \"  IPv6: $(($_.IPv6Address | ForEach-Object IPAddress) -join '', '')\"\n  \"  Gateway: $(($_.IPv4DefaultGateway | ForEach-Object NextHop) -join '', '')\"\n  \"  DNS: $(($_.DNSServer | ForEach-Object ServerAddresses) -join '', '')\"\n  ''''\n}"},{"osFamily":"linux","shell":"sh","script":"echo \"Addresses:\"\nip -brief address 2>/dev/null || ip address\necho\necho \"Routes:\"\nip route\necho\necho \"DNS:\"\nif command -v resolvectl >/dev/null 2>&1 && resolvectl dns 2>/dev/null; then\n  :\nelse\n  grep -v ''^#'' /etc/resolv.conf\nfi"}]', '[]', '["00000000-0000-4000-8000-00000000a11a"]', 'reads-only', 0, 0, 60000, 1, 0, 0, NULL);--> statement-breakpoint
INSERT INTO `saved_commands` (`id`, `name`, `description`, `scripts`, `parameters`, `machine_group_ids`, `effect`, `enabled`, `ai_unattended`, `timeout_ms`, `version`, `created_at`, `updated_at`, `updated_by`) VALUES ('00000000-0000-4000-8000-00000005c008', 'Installed software', 'Every installed program or package, with its version.', '[{"osFamily":"windows","shell":"powershell","script":"$keys = ''HKLM:\\Software\\Microsoft\\Windows\\CurrentVersion\\Uninstall\\*'',\n  ''HKLM:\\Software\\WOW6432Node\\Microsoft\\Windows\\CurrentVersion\\Uninstall\\*''\nGet-ItemProperty $keys -ErrorAction SilentlyContinue | Where-Object DisplayName |\n  Sort-Object DisplayName -Unique |\n  Select-Object DisplayName, DisplayVersion, Publisher |\n  Format-Table -AutoSize | Out-String -Width 250"},{"osFamily":"linux","shell":"sh","script":"if command -v dnf >/dev/null 2>&1 || command -v zypper >/dev/null 2>&1; then\n  rpm -qa --qf ''%{NAME} %{VERSION}-%{RELEASE}\\n'' | sort\nelif command -v apt-get >/dev/null 2>&1; then\n  dpkg-query -W -f ''${Package} ${Version}\\n'' | sort\nelse\n  echo \"No dnf, apt or zypper on this machine.\"\n  exit 1\nfi"}]', '[]', '["00000000-0000-4000-8000-00000000a11a"]', 'reads-only', 0, 0, 120000, 1, 0, 0, NULL);
